from itertools import combinations
v=13
base=[(0,1,4),(0,2,7)]
blocks=[]
for b in base:
    for t in range(v):
        blocks.append(tuple(sorted(((x+t)%v for x in b))))
# verify pair uniqueness
pairs={}
for i,b in enumerate(blocks):
    for p in combinations(b,2):
        if p in pairs: print('dup',p,pairs[p],i)
        pairs[p]=i
print(len(blocks), len(pairs))
