    adj[u].add(v); adj[v].add(u)
print([len(adj[i]) for i in range(n)], min(map(len,adj)), max(map(len,adj)))
# girth BFS
from collections import deque
g=10**9
for s in range(n):
    dist=[-1]*n; par=[-1]*n
    dist[s]=0; q=deque([s])
    while q:
        u=q.popleft()
        for v in adj[u]:
            if dist[v]<0:
                dist[v]=dist[u]+1; par[v]=u; q.append(v)
            elif par[u]!=v and par[v]!=u:
                g=min(g,dist[u]+dist[v]+1)
print('girth',g)
